import type { IconifyJSON } from '@iconify/types';
import { addCollection } from '@iconify/vue';
import { type Ref, ref } from 'vue';

// Offline registration of the projects public pages' icon sets (B78: no
// runtime calls to the Iconify API). The tech-tag chips render devicon
// glyphs and the card "Sources" buttons render the simple-icons GitHub
// mark; heroicons are already registered at the app entries
// (resources/js/iconRegistry.ts). The subsets generated by
// `npm run icons:build` (scripts/build-icon-subsets.mjs) keep the packs'
// payloads at tens of KB and still ship to the app only through this
// lazy dynamic import. The `iconsReady` ref lets consumers render their
// `<Icon>` elements only after registration — a non-reactive storage
// would leave them empty until an unrelated re-render.

let registered = false;
const iconsReady = ref(false);

export function useProjectsIconsReady(): Ref<boolean> {
    return iconsReady;
}

export function ensureProjectsIcons(): void {
    if (registered || typeof window === 'undefined') {
        return;
    }

    registered = true;

    void Promise.all([
        import('@/iconSubsets/devicon.json'),
        import('@/iconSubsets/simple-icons.json'),
    ])
        .then(([devicon, simpleIcons]) => {
            addCollection((devicon as { default: IconifyJSON }).default);
            addCollection((simpleIcons as { default: IconifyJSON }).default);
            iconsReady.value = true;
        })
        .catch(() => {
            // Iconify falls back to its runtime fetch on an unregistered
            // name; the icons stay empty until a later registration.
            registered = false;
        });
}
